from pathlib import Path
import html, json, re, shutil
from experience import render, examples, credits, licence, figure, REPORT_INSERTS
from opportunity import opportunity_intro, opportunity_body

ROOT=Path(__file__).resolve().parent
WORK=ROOT/'data'
BASE='https://auraofintelligence.github.io/sovereign-capacity-lab/'
sources=json.loads((WORK/'research-sources.json').read_text(encoding='utf-8'))
sources.update(json.loads((WORK/'australian-opportunity-sources.json').read_text(encoding='utf-8')))
sources.update({
 'atlas':{'org':'Luke Nathan Hayes Strange But True and Aura of Intelligence','date':'First substantive build 27 August 2026; checked 7 November 2026','title':'Extreme Matter Atlas and its element dataset','url':'https://auraofintelligence.github.io/extreme-matter-atlas/'},
 'jra':{'org':'Luke Nathan Hayes','date':'Public site checked 7 November 2026','title':'Joyful Responsible Abundance','url':'https://auraofintelligence.github.io/joyful-responsible-abundance/index.html'},
 'fair-go-public':{'org':'Luke Nathan Hayes','date':'Public proposal checked 7 November 2026','title':'Installing the Missing Middle','url':'https://auraofintelligence.github.io/installing-the-missing-middle/'},
 'games':{'org':'Queensland Government','date':'Games dates checked 7 November 2026','title':'A Games for all of Queensland','url':'https://www.qld.gov.au/government/strategies-initiatives/initiatives/brisbane2032/a-games-for-all-of-queensland'},
 'population-data':{'org':'Centre for Population Commonwealth of Australia','date':'9 January 2026 underlying workbook; population at 30 June','title':'National population projections 2024 to 2025 through 2035 to 2036','url':'https://population.gov.au/publications/statements/2025-population-statement'},
})
pages=[
 ('index.html','overview','Start here','Sovereign Capacity Lab','Change the assumptions. Follow the atoms, machines and electricity through to useful local capability.'),
 ('power.html','power','Power budget','Power and the clean energy budget','Build new capability while preserving the electricity allocated to clean-energy transition and essential development.'),
 ('machines.html','machines','Robots and repair','Machines materials and long service lives','Explore annual production, surviving fleets, refurbishment, motors and the material in each machine.'),
 ('storage.html','storage','Solar and storage','Generation storage and substitute chemistries','Separate power ratings, delivered energy, losses and the atomic materials needed by a chosen design.'),
 ('matter.html','matter','Elements and feedstocks','From atomic elements to industrial supply','Substitute a source mineral, change its grade and recovery, then compare the required output with existing industry.'),
 ('ledger.html','ledger','Project material ledger','Put the whole project in the material ledger','Create a bill of materials for factories, grids, robots, panels, service parts and other equipment.'),
 ('space.html','space','Space infrastructure','Orbital power mass and transport','Size on-board generation, heat rejection, payload transport and power delivered to other users.'),
 ('australia.html','australia','Australia and 2032','Australian capability before and beyond 2032','Connect population growth, domestic industry, civic robots, sovereign compute and global exports.'),
 ('manufacture-australia.html','opportunity','Australian manufacturing','Build robots in Australia','Manufacture civic robots for Australian communities and export. Size the factories, costs, supply chains and locally governed capability.'),
 ('report.html','report','Read the paper','Mining materials and power','Read the integrated research paper with dated references and download the Word version.'),
 ('sources.html','sources','Sources and methods','Evidence assumptions and reproducible methods','Inspect the dated sources, the calculation boundaries and the relationships between the projects.'),
]
pages += [
 ('visuals.html','visuals','Image credits','Photographs figures and generated concepts','Check image dates, original sources, reuse licences and exact generation prompts.'),
 ('licence.html','licence','Strange But True licence','Strange But True Public Source Licence','Read the terms for this public source project and the separate licences for photographs and adapted data.'),
 ('site-map.html','directory','All pages','Find your way through the laboratory','Move between the calculators, integrated paper, evidence and image credits.'),
]
esc=html.escape
def link(url,label):return f'<a href="{esc(url,quote=True)}" target="_blank" rel="noopener noreferrer">{esc(label)}</a>'
def prose_line(t):
 result=[];last=0
 for m in re.finditer(r'\{([a-z0-9-]+)\|([^{}]+)\}',t):
  result.append(esc(t[last:m.start()]));key,label=m.groups();result.append(link(sources[key]['url'],label));last=m.end()
 result.append(esc(t[last:]));return ''.join(result)

intro='''<p class="eyebrow">A Fair Go in the Age of Superintelligence</p><p class="lead-rule">Joyful responsible abundance needs useful machines, reliable clean power and people who retain authority over both.</p><p>This laboratory connects Luke Nathan Hayes's mining and materials paper with Joyful Responsible Abundance and Extreme Matter Atlas. It gives the proposed missing middle a physical account: what to build, what it contains, how to power it and how to keep it working.</p><p>The global manufacturing scenario and an Australian civic rollout are separate scales. Start with the power budget or change the year below. Then examine the material, mineral, repair and infrastructure requirements.</p>'''
routes='<ol class="route-list">'+''.join(f'<li><span class="route-number">{i:02}</span><div><a href="{f}">{esc(title)}</a><p>{esc(desc)}</p></div></li>' for i,(f,key,nav,title,desc) in enumerate(pages[1:9],1))+'</ol>'
connections='''<section class="prose"><h2>Where these projects meet</h2><ul class="connection-list"><li><a href="https://auraofintelligence.github.io/joyful-responsible-abundance/index.html" target="_blank" rel="noopener noreferrer">Joyful Responsible Abundance</a> sets out the social purpose, capacity and ownership arrangements.</li><li><a href="https://auraofintelligence.github.io/extreme-matter-atlas/" target="_blank" rel="noopener noreferrer">Extreme Matter Atlas</a> explores elements, crystal structures, metamaterials and material discovery. Its atomic dataset powers the formula calculations here.</li><li><a href="https://auraofintelligence.github.io/installing-the-missing-middle/" target="_blank" rel="noopener noreferrer">A Fair Go in the Age of Superintelligence and the Australian installation plan</a> connect postcode-level compute with personal, local and national sovereignty.</li><li><a href="https://auraofintelligence.github.io/gajra-earth-claude-build/" target="_blank" rel="noopener noreferrer">GAJRA Earth</a>, the Global Association for Joyful Responsible Abundance on Earth, extends the missing middle through distributed capability around the world.</li><li><a href="https://auraofintelligence.github.io/i-C-infinity-music-universe/albums/a-protopian-gambit/" target="_blank" rel="noopener noreferrer">A Protopian Gambit</a>, including We Go Beyond and Joyful Responsible Abundance, expresses the cultural purpose of building a world people want to keep participating in.</li></ul></section>'''
australia_intro='''<section class="prose"><h2>A practical deadline and an ongoing legacy</h2><p>The Brisbane 2032 Olympic Games run from 23 July to 8 August, followed by the Paralympic Games from 24 August to 5 September. <a href="https://www.qld.gov.au/government/strategies-initiatives/initiatives/brisbane2032/a-games-for-all-of-queensland" target="_blank" rel="noopener noreferrer">Queensland Government dates, checked 7 November 2026</a>.</p><p>Hayes proposes using that horizon to develop enduring community capability: trained crews, local computing, civic robots, repair workshops, reliable power and public learning spaces. These calculators size a proposed civic programme. Games operations and official procurement require their own published equipment and load schedules.</p><p>The physical missing middle consists of locally governed infrastructure. Individual Auras are software that can use it. Civic robots support useful work and resilience under distributed authority. A single organisation does not command the whole network.</p></section>'''
method='''<div class="prose"><h2>Power allocation comes before deployment</h2><p>Reserve new clean electricity for fossil replacement, essential development and replacement of retired clean supply. The remaining annual energy can support additional compute and robots. The model reports gaps in both protected allocations and new project supply. It does not assume UN Sustainable Development Goals or clean-energy transition targets give way to machines.</p><p>Annual energy is a first check. Dependable delivery needs hourly demand, weather, storage power and duration, network limits and outages. The repeated-day solar illustration tests a simplified day; it is not a weather or grid reliability model. Storage losses are charged at the source. Storage is not counted as generation.</p><h2>Units and boundaries</h2><p>One gigawatt sustained for a year supplies 8.76 terawatt-hours. Rated compute is multiplied by its average operating load and facility power factor before conversion to electricity. The 485 terawatt-hour baseline already includes facility overhead. An electricity forecast is never multiplied by that overhead a second time.</p><p>Annual new machines, accumulated manufacture and machines still operating are separate quantities. Final losses are applied to cohorts. Service parts keep retained structures productive. The scenario does not retire a complete robot or rack on a fixed five-year schedule.</p><p>External factory feed equals finished material divided by net yield after internal scrap reuse. The primary share requires new extraction; the secondary share requires qualified and allocated material. Chemical formulae convert compound grade to elemental grade once. Primary aluminium, recycled aluminium, end-use demand and installed smelter capacity remain separate series.</p><h2>Substitution and discovery</h2><p>Enter an alternative cathode or photovoltaic absorber formula, its capacity or conversion performance, density and thickness. The calculator finds the atomic material fractions. That calculation sizes a chosen design. It does not establish a synthesis route, durability or accepted factory output.</p><p>Extreme Matter Atlas supplies a path from elements to GNoME, crystals and metamaterials. Its dataset includes estimated properties. The formula engine here uses tabulated atomic masses. Research can change the material or performance assumptions as measurements become available.</p><h2>Market demand and added project inventories</h2><p>The default copper path uses S and P Global's January 2026 figures of 28, 33, 38 and 42 million tonnes in 2025, 2030, 2035 and 2040. The main four-sector forecast treats humanoid manufacturing separately. Aluminium uses McKinsey's July 2025 end-use path of 106 million tonnes in 2025 and 130 million in 2035, with its own supply mix described in the paper.</p><p>The calculator adds the selected robot batch after subtracting any entered allowance already embedded in the market outlook. Faster data-centre, orbital or generation programmes need their own project inventories and replacement of the relevant market sector allowance. The project ledger helps build that inventory. It should not be added wholesale to a forecast already counting the same equipment.</p><h2>Explore the changing years</h2><p>The calculator opens at 2026 and initially plots every year through 2036. Move the year slider, use the planning-horizon buttons or select a point on an annual graph. The chart end can extend to 2040. Selected-year readings, year-by-year tables and CSV downloads use the same calculation engine. Pin current assumptions before changing an input to compare annual paths.</p><p>The power plan has a separate completion year. Its additional generation accumulates from zero above the 2025 base using the entered annual construction multiplier, reaches the entered capacities at the plan year and then holds. Protected annual allocations grow linearly to that same year and then hold. These editable paths are scenario assumptions dated 7 November 2026. They are not measured annual additions. Existing 2025 compute electricity remains in the demand base.</p><p>The manufacturing programme starts in the entered first production year. Earlier views contain no units from that programme. Population is interpolated at a constant compound rate between June 2025 and the entered population plan year, then extrapolated at that rate. Civic fleet figures size a service requirement. Engineering curves show the current storage, feedstock, orbital or project design inputs; annual topics show the time paths.</p><h2>Your scenario stays with you</h2><p>All calculations run in this browser. This site has no account system, analytics or model API. A tab-local scenario carries settings between pages. Download JSON to retain every input, download CSV for results, or copy a link that includes the scenario. Anyone receiving that link can read its inputs. Reset returns to the dated default scenario.</p><h2>Dates and reproducibility</h2><p>The research and default assumptions are dated 7 November 2026. Source publication dates appear in the register below. Company targets and proposed rollouts retain their status as dated intentions. Formulas are visible beside the results. The public repository includes automated tests for dimensional conversions, mass balance, survival and protected power allocation.</p><h2>Project links and credits</h2><p>Created for Luke Nathan Hayes with Codex. The element dataset is adapted from Extreme Matter Atlas by Luke Nathan Hayes, Strange But True and Aura of Intelligence, an original Luke and Claude project. It is used under its Strange But True Public Source Licence. The site and adapted data retain public source licensing with commercial rights reserved to the author.</p></div>'''

manuscript=(WORK/'research-manuscript.txt').read_text(encoding='utf-8')
used=set(re.findall(r'\{([a-z0-9-]+)\|',manuscript))|{'atlas','jra','fair-go-public','games','population-data'}
sources={k:v for k,v in sources.items() if k in used}
(ROOT/'data/sources.json').write_text(json.dumps(sources,indent=2),encoding='utf-8')
blocks=[];toc=[];index=0
current_section="";paragraph_count=0;inserted=set()
for text in manuscript.split('\n\n'):
 text=text.strip()
 if not text or text=='[[PAGEBREAK]]':continue
 if text.startswith('# '):continue
 if text.startswith('## '):
  current_section=text[3:];paragraph_count=0
  index+=1;title=text[3:];anchor=f'section-{index}';toc.append((anchor,title));blocks.append(f'<h2 id="{anchor}" class="report-section">{esc(title)}</h2>')
 elif text.startswith('### '):blocks.append(f'<h3>{esc(text[4:])}</h3>')
 else:
  blocks.append('<p>'+prose_line(text)+'</p>');paragraph_count+=1
  placement=REPORT_INSERTS.get(current_section)
  if placement and paragraph_count==placement[0]:blocks.append(figure(placement[1]));inserted.add(placement[1])
  if current_section=='Generation and storage also require materials' and paragraph_count==6:blocks.append(figure('figure-day-storage'))
  if text.startswith('Those quantities show the scale of the industrial race.'):blocks.append(figure('figure-factory-floor'))
assert len(inserted)==len(REPORT_INSERTS), f'Missing inline figure placements: {set(x[1] for x in REPORT_INSERTS.values())-inserted}'
docname='Mining_Materials_Power_and_Australian_Manufacturing_2026-11-07.docx'
assert (ROOT/'documents'/docname).exists(), 'Place the verified Word paper in documents before rebuilding.'
report='<div id="paper-start"></div><p class="read-tools"><a class="button" href="documents/'+docname+'">Download the Word paper</a><button class="secondary" type="button" onclick="window.print()">Print the reading edition</button></p><details><summary>Paper contents</summary><ol class="report-toc">'+''.join(f'<li><a href="#{a}">{esc(t)}</a></li>'for a,t in toc)+'</ol></details><article class="prose">'+''.join(blocks)+'</article>'
register='<h2 id="references">Dated reference register</h2><ol class="reference-list prose">'+''.join('<li>'+esc(s['org'])+'. '+esc(s['date'])+'. '+link(s['url'],s['title'].replace('\u2014',', '))+'.</li>'for s in sources.values())+'</ol>'
toolbar='''<div class="toolbar" aria-label="Scenario tools"><button type="button" data-action="export">Save scenario JSON</button><button type="button" data-action="import">Load scenario</button><button type="button" data-action="csv">Download result CSV</button><button type="button" data-action="share">Copy scenario link</button><button type="button" data-action="reset">Reset inputs</button><input id="import-file" type="file" accept=".json,application/json" hidden></div><p id="scenario-status" role="status" aria-live="polite">Default scenario dated 7 November 2026.</p><p id="notice" role="alert"></p>'''
for filename,key,nav,title,desc in pages:
 iscalc=key in ['overview','power','machines','storage','matter','ledger','space','australia','opportunity']
 content=intro if key=='overview' else australia_intro if key=='australia' else opportunity_intro() if key=='opportunity' else ''
 if iscalc:content+=toolbar+'<noscript><p>Calculators need JavaScript. The <a href="report.html">complete paper</a> and <a href="sources.html">dated sources and methods</a> can be read without it.</p></noscript><div id="calculator"></div>'+examples(key)
 if key=='overview':content+=routes+connections
 if key=='australia':content+='<p class="prose"><a class="button" href="manufacture-australia.html">Build robots in Australia for domestic use and export</a></p>'+connections
 if key=='opportunity':content+=opportunity_body(prose_line)
 if key=='report':content+=report
 if key=='sources':content+=method+connections+register
 if key=='visuals':content+=credits()
 if key=='licence':content+=licence()
 if key=='directory':content+='<ol class="page-directory">'+''.join(f'<li><a href="{f}">{esc(n)}</a><p>{esc(d)}</p></li>'for f,k,n,t,d in pages)+'</ol>'
 htmltext=render(filename,key,title,desc,content,pages,iscalc,docname)
 assert '\u2014' not in htmltext,filename
 (ROOT/filename).write_text(htmltext,encoding='utf-8')
(ROOT/'.nojekyll').write_text('',encoding='utf-8')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p[0]+'</loc></url>'for p in pages)+'</urlset>',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n',encoding='utf-8')
print(json.dumps({'pages':len(pages),'sources':len(sources),'report_words':len(manuscript.split())}))

(ROOT/'site.webmanifest').write_text(json.dumps({'name':'Sovereign Capacity Lab','short_name':'Capacity Lab','description':'Atoms to useful local capability','start_url':'./','scope':'./','display':'standalone','background_color':'#f4f4e8','theme_color':'#173e35','icons':[{'src':'icon-192.png','sizes':'192x192','type':'image/png'},{'src':'icon-512.png','sizes':'512x512','type':'image/png'}]},indent=2),encoding='utf-8')
(ROOT/'llms.txt').write_text('# Sovereign Capacity Lab\n\nResearch and default assumptions dated 7 November 2026. Local scenario tools for materials, clean energy, robots, compute and distributed capability.\n\n'+''.join(f'- [{n}]({BASE+f}): {d}\n'for f,k,n,t,d in pages)+'\nPublic source under the Strange But True Public Source Licence. Commercial rights reserved. Photograph licences are listed separately in image credits.\n',encoding='utf-8')
error_content='<div class="prose"><p>This address does not match a page in the laboratory.</p><p><a class="button" href="'+BASE+'">Return to the laboratory</a> <a href="'+BASE+'site-map.html">Browse all pages</a></p></div>'
error_page=render('site-map.html','directory','Page not found','Find a calculator, the research paper or its sources.',error_content,pages,False,docname)
# Absolute base keeps links and assets usable for nested missing URLs on GitHub Pages.
error_page=error_page.replace('<head>','<head><base href="'+BASE+'"><meta name="robots" content="noindex">')
(ROOT/'404.html').write_text(error_page,encoding='utf-8')
